create function pg_temp.fail_finish() returns trigger language plpgsql as $$begin
  if new.command_id=pg_temp.fid('late') then
    raise exception using errcode='P0001',message='CALENDAR_TEST_LATE_FAILURE';
  end if;
  return new;
end $$;
