  50,'AC-401 version history page is bounded');
select is(jsonb_array_length(api.people_calendar_versions(pg_temp.fid('tenant'),pg_temp.fid('entity'),
  pg_temp.fid('branch'),pg_temp.fid('calendar'),(select response#>>'{items,49,id}'
  from calendar_response where name='page')::uuid)->'items'),3,'AC-401 UUID cursor retrieves only remaining versions');
reset role;

do $$
declare v_failed text;
begin
  select string_agg(message, E'\n') into v_failed
  from calendar_assertions where message like 'not ok%';
  if v_failed is not null then
    raise exception using errcode='P0001', message=v_failed;
  end if;
end $$;
select * from finish(true);
rollback;
